import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`massage-therapist-audit`,heroTitle:`Audit your massage therapy website in minutes`,heroSubtitle:`Perplexity Computer analyzes your massage therapy site, service positioning, booking path, reviews, and local visibility, then turns the findings into a clear growth plan.`,inputUrlCta:`Audit my practice`,inputUrlPlaceholder:`yourmassagepractice.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this massage therapy practice. 1) Review the website for service clarity, modality descriptions, therapist credentials, pricing, mobile UX, and booking friction. 2) Audit local SEO, Google Business Profile signals, reviews, and trust cues. 3) Compare against top nearby massage therapists and wellness studios for offer structure, positioning, and appointment CTAs. 4) Recommend the highest-impact fixes for more bookings, gift card sales, memberships, and local search visibility. 5) Deliver a prioritized action plan with rewritten copy, booking-flow improvements, and growth recommendations.`,heroOverlaySteps:[`Reviewing your massage therapy site, services, credentials, and booking flow`,`Benchmarking nearby practices on reviews, offers, and local visibility`,`Finding the trust, copy, and UX gaps that can reduce appointment volume`,`Booking fixes, local SEO priorities, and service messaging ready to use`],generatingSteps:[`Visiting {url} to inspect your massage therapy website and booking path`,`Designing an agent to compare nearby practices, reviews, and local search signals`,`Configuring service copy rewrites, trust improvements, and conversion fixes`,`Setting up a prioritized action plan for more appointments`],featureSectionTitle:`From wellness interest to booked sessions`,featureCardTitles:[`Connects to your practice stack`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your massage therapy audit into site review, service positioning, local SEO, and competitor research, then routes each step to the right model.`,`Google Business Profile, booking pages, Docs, Sheets, and planning tools can all feed one workflow so recommendations stay organized.`,`Service rewrites. Booking-flow improvements. Review and trust guidance. Local SEO priorities. Computer gives you updates tied to more sessions.`],capabilitySectionTitle:`Your massage practice growth team, on autopilot`,capabilitySectionSubtitle:`Paste your massage therapy URL, step away, and come back to a clearer plan to drive more bookings.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review service pages, modality explanations, therapist credentials, pricing clarity, booking flow, and mobile UX.`},{title:`Local Search Review`,description:`Computer can assess Google Business Profile strength, review reputation, and local SEO setup to show where nearby practices are winning.`},{title:`Trust & Offer Positioning`,description:`Computer can rewrite service copy, membership framing, and CTA language so visitors understand why to book with your practice.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across Google Business Profile, booking tools, Docs, and Sheets so your team can execute quickly.`},{title:`Remember Your Modalities`,description:`Computer can remember your specialties, packages, membership offers, and ideal clients so future audits start with the right context.`},{title:`Monitor Booking Signals`,description:`Computer can revisit your online presence over time, flag when conversion signals slip, and suggest the next fix most likely to improve bookings.`}]});export{t as default};
